Seeded generator:

```ts
function createSeries(seed: number, base: number, amplitude: number, noise: number): number[] {
  const rand = mulberry32(seed);
  let drift = 0;
  return Array.from({length: POINTS}, (_, i) => {
    drift = clamp(drift + (rand() - 0.5) * 2, -10, 10);
    const dayWave = Math.sin((i / POINTS) * Math.PI * 4);
    return round(base + dayWave * amplitude + drift * noise + (rand() - 0.5) * 2 * noise);
  });
}
```

